        public readonly string Id,Title,Category,Limitation;
        public readonly string[] Keywords,Steps;
        internal VrGuideArticle(string id,string title,string category,string keywords,string limitation,params string[] steps)
        {Id=id;Title=title;Category=category;Keywords=keywords.Split('|');Limitation=limitation;Steps=steps;}
    }
