        public static IReadOnlyList<VrGuideArticle> All=>articles;
        public static IReadOnlyList<VrGuideArticle> Articles=>articles;
        static string[] Words(string value)
        {
            var result=new List<string>();foreach(Match word in Regex.Matches((value??"").ToLowerInvariant(),@"[\p{L}\p{Nd}]+"))result.Add(word.Value);return result.ToArray();
        }
        static int Match(string[] words,string term,int exact,int prefix)
        {int score=0;foreach(string word in words)if(word==term)score=Math.Max(score,exact);else if(word.StartsWith(term,StringComparison.Ordinal))score=Math.Max(score,prefix);return score;}
        sealed class Ranked{public VrGuideArticle Article;public int Score,Order;}
        public static IReadOnlyList<VrGuideArticle> Search(string query)
        {
            query=(query??"").Trim();if(query.Length==0)return articles;
            if(query.Length>MaximumQueryLength)query=query.Substring(0,MaximumQueryLength);
            var terms=Words(query);if(terms.Length==0)return Array.Empty<VrGuideArticle>();
            var matches=new List<Ranked>();int order=0;
            foreach(var article in articles)
            {
                var title=Words(article.Title);var keywords=Words(string.Join(" ",article.Keywords));var category=Words(article.Category);
                var body=Words(string.Join(" ",article.Steps)+" "+article.Limitation);int score=0;bool all=true;
                foreach(string term in terms)
                {
                    int best=Math.Max(Match(title,term,120,90),Math.Max(Match(keywords,term,80,60),Math.Max(Match(category,term,40,30),Match(body,term,20,10))));
                    if(best==0){all=false;break;}score+=best;
                }
                if(all){if(article.Title.Equals(query,StringComparison.OrdinalIgnoreCase))score+=400;matches.Add(new Ranked{Article=article,Score=score,Order=order});}order++;
            }
            matches.Sort((a,b)=>a.Score!=b.Score?b.Score.CompareTo(a.Score):a.Order.CompareTo(b.Order));
            var result=new List<VrGuideArticle>();foreach(var match in matches)result.Add(match.Article);return result.AsReadOnly();
        }
    }
